"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def SplitSentence(sentence):
    words = []
    current_word = ''
    for __reserved_keyword__char in sentence:
        if (__reserved_keyword__char == ' '):
            if (current_word != ''):
                words.append(current_word)
                current_word = ''
        else:
            current_word = (current_word + __reserved_keyword__char)
    if (current_word != ''):
        words.append(current_word)
    return words

print(SplitSentence("This is a sentence!"))
